function Scene({pieces=5,empty=false}:{pieces?:number;empty?:boolean}){return <svg className="scene-art" viewBox="0 0 520 340" role="img" aria-label={empty?'Sala vacía · ejemplo':'Escena de ejemplo · Backing, mesa y globos'}><path className="floor" d="M40 258 243 162 485 245 282 329Z"/>{!empty&&<><path className="backing" d="M212 248V120a58 58 0 0 1 116 0v107Z"/><path className="piece" d="m186 242 103-42 101 37-101 45Z"/><path className="piece" d="m201 251 10 48 8-3-4-40M367 248l-8 45-8-4 3-36"/>{Array.from({length:pieces+6},(_,i)=>{const a=Math.PI*.96+i/(pieces+5)*Math.PI;return <ellipse key={i} className={i%3===0?'neutral-balloon':'balloon'} cx={271+93*Math.cos(a)} cy={173+93*Math.sin(a)} rx={16+i%3*2} ry={20+i%2*3} transform={`rotate(${i*13} ${271+93*Math.cos(a)} ${173+93*Math.sin(a)})`}/>})}</>}<path className="rule" d="m65 280 36 12m-18-17-18 5 5 16"/></svg>}
