 const [name,setName]=React.useState(fixture.name);const [draftName,setDraftName]=React.useState('');const [retainedDraft,setRetainedDraft]=React.useState(false);const [invalid,setInvalid]=React.useState(m.state==='invalid');const [notice,setNotice]=React.useState('');const [newDraft,setNewDraft]=React.useState(m.state==='unsaved');const [localStatus,setLocalStatus]=React.useState('');const [imported,setImported]=React.useState(m.state==='imported'||fixture.imported);const [declined,setDeclined]=React.useState(false);const [pendingStart,setPendingStart]=React.useState('');
